async function db(sql, params = []) {
  if (!process.env.DB_HOST || !process.env.DB_USER || !process.env.DB_NAME) throw new Error('DB env not configured');
  if (!pool) {
    const mysql = await import('mysql2/promise');
    pool = mysql.createPool({ host: process.env.DB_HOST, user: process.env.DB_USER, password: process.env.DB_PASSWORD, database: process.env.DB_NAME, waitForConnections: true, connectionLimit: 5 });
  }
  const [rows] = await pool.execute(sql, params);
  return rows;
}
function esc(v) { return String(v || '').replace(/[&<>"']/g, m => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[m])); }
function slugify(v) { return String(v || 'post').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '') || 'post'; }
function activeSort(rows) { return (rows || []).filter(x => Number(x.is_active ?? 1) !== 0).sort((a, b) => Number(a.sort_order || 0) - Number(b.sort_order || 0)); }
function lightBg(_bg, i = 0) { return lightPalette[i % lightPalette.length]; }
function arrOrFallback(rows, fallback) { return Array.isArray(rows) && rows.length ? rows : fallback; }
function cookieMap(req) { return Object.fromEntries((req.headers.cookie || '').split(';').filter(Boolean).map(v => { const i = v.indexOf('='); return [decodeURIComponent(v.slice(0, i).trim()), decodeURIComponent(v.slice(i + 1).trim())]; })); }
function signSession(user) { const payload = Buffer.from(JSON.stringify({ email: user.email, role: user.role, exp: Date.now() + 7 * 86400000 })).toString('base64url'); const sig = crypto.createHmac('sha256', sessionSecret).update(payload).digest('base64url'); return payload + '.' + sig; }
function verifySession(token) { try { const [payload, sig] = String(token || '').split('.'); const expected = crypto.createHmac('sha256', sessionSecret).update(payload).digest('base64url'); if (!crypto.timingSafeEqual(Buffer.from(sig || ''), Buffer.from(expected))) return null; const u = JSON.parse(Buffer.from(payload, 'base64url').toString()); return Date.now() < u.exp ? u : null; } catch { return null; } }
function currentUser(req) { return verifySession(cookieMap(req).ymi_admin); }
function allow(user, r) { return user && (user.role === 'super_admin' || r.includes(user.role)); }
function requireRole(r) { return (req, res, next) => { const u = currentUser(req); if (!allow(u, r)) return res.status(401).json({ success: false, message: 'Permission denied' }); req.user = u; next(); }; }
function requirePage(r) { return (req, res, next) => { const u = currentUser(req); if (!allow(u, r)) return res.redirect('/login'); req.user = u; next(); }; }
async function loadPosts() { try { const r = await db('SELECT id,title,category,excerpt,content,language,cover_image,created_at FROM posts ORDER BY id DESC LIMIT 300'); return arrOrFallback(r, memoryPosts); } catch { try { const r = await db('SELECT id,title,category,excerpt,content,created_at FROM posts ORDER BY id DESC LIMIT 300'); return arrOrFallback(r.map(x => ({ ...x, language: 'en', cover_image: '' })), memoryPosts); } catch { return memoryPosts; } } }
async function loadMedia() { try { return arrOrFallback(await db('SELECT * FROM media_assets ORDER BY id DESC LIMIT 300'), memoryMedia); } catch { return memoryMedia; } }
async function loadHomepage() { try { const heroBanners = await db('SELECT * FROM hero_banners ORDER BY sort_order,id'); const subHeroBanners = await db('SELECT * FROM sub_hero_banners ORDER BY sort_order,id'); const mediaGallery = await db('SELECT * FROM media_gallery ORDER BY sort_order,id'); const tiles = await db('SELECT * FROM homepage_tiles ORDER BY sort_order,id'); return { heroBanners: arrOrFallback(heroBanners, memoryHome.heroBanners), subHeroBanners: arrOrFallback(subHeroBanners, memoryHome.subHeroBanners), mediaGallery: arrOrFallback(mediaGallery, memoryHome.mediaGallery), tiles: arrOrFallback(tiles, memoryHome.tiles) }; } catch { return memoryHome; } }
async function saveUpload(dataUrl, name = 'media') { const match = String(dataUrl || '').match(/^data:(.+?);base64,(.+)$/); if (!match) return dataUrl || ''; const ext = match[1].includes('svg') ? 'svg' : match[1].includes('png') ? 'png' : match[1].includes('webp') ? 'webp' : 'jpg'; const filename = slugify(name) + '-' + Date.now() + '.' + ext; await fsp.writeFile(path.join(uploadDir, filename), Buffer.from(match[2], 'base64')); return '/uploads/' + filename; }
function tableFor(s) { return { heroBanners: 'hero_banners', subHeroBanners: 'sub_hero_banners', mediaGallery: 'media_gallery', tiles: 'homepage_tiles' }[s]; }
function humanFallback(category, title, notes, language = 'en') {
  const c = category || 'Viral India';
  const clean = String(notes || '').trim();
  const seed = String(title || '').trim() || clean.split(/[.?!\n]/)[0].slice(0, 68) || c;
  const t = seed.includes(':') ? seed : `${seed}: A Human Story from India`;
  const para1 = clean ? `The story begins with a simple observation: ${clean}.` : `The story begins with ${seed}, a subject that deserves a clear and grounded explanation.`;
  const para2 = `What makes this important is not just the trend around it, but the way it connects people, place and memory. A good India story should not sound like a brochure; it should help the reader understand why the moment feels alive.`;
  const para3 = `For a global reader, the value is context. Instead of adding noise, this piece keeps the focus on ${seed}, its cultural feeling, and the human detail behind it.`;
  const hindi = language !== 'en' ? `\n\nहिंदी भाव: यह लेख विषय को सरल, मानवीय और स्पष्ट भाषा में समझाता है, बिना अनावश्यक जानकारी जोड़े।` : '';
  return { title: t, category: c, language, excerpt: `${seed} explained in a clear, human and magazine-style voice, with focus on context instead of noise.`, content: `${t}\n\n${para1}\n\n${para2}\n\n${para3}${hindi}`, hashtags: ['#India', '#VividIndia', '#' + c.replace(/\s/g, ''), '#HumanStories'] };
}
