async function validateAdmin(email, pass) { try { const rows = await db('SELECT email,password,role,status FROM users WHERE email=? LIMIT 1', [email]); const u = rows[0]; if (u && u.status !== 'inactive') { const bcrypt = await import('bcryptjs'); if (await bcrypt.default.compare(pass, u.password)) return { email: u.email, role: u.role || 'admin' }; } } catch {} if (process.env.ADMIN_EMAIL && process.env.ADMIN_PASSWORD && email === process.env.ADMIN_EMAIL && pass === process.env.ADMIN_PASSWORD) return { email, role: 'super_admin' }; return null; }
async function insertPost(p) { try { await db('INSERT INTO posts (title,slug,excerpt,content,category,status,language,cover_image,meta_title,meta_description,seo_keywords) VALUES (?,?,?,?,?,?,?,?,?,?,?)', [p.title, slugify(p.title), p.excerpt, p.content + '\n\n' + (p.hashtags || ''), p.category, 'published', p.language || 'en', p.cover_image || '', p.meta_title || p.title, p.meta_description || p.excerpt, p.seo_keywords || 'India,Vivid India']); return true; } catch { try { await db('INSERT INTO posts (title,slug,excerpt,content,category,status) VALUES (?,?,?,?,?,?)', [p.title, slugify(p.title), p.excerpt, p.content + '\n\n' + (p.hashtags || ''), p.category, 'published']); return true; } catch { return false; } } }
async function saveHomeDb(section, item, id) { try { if (section === 'heroBanners') { if (id) await db('UPDATE hero_banners SET title=?,subtitle=?,description=?,button1_text=?,button1_link=?,button2_text=?,button2_link=?,image_url=?,sort_order=?,is_active=? WHERE id=?', [item.title,item.subtitle,item.description,item.button1_text,item.button1_link,item.button2_text,item.button2_link,item.image_url,item.sort_order,item.is_active,id]); else await db('INSERT INTO hero_banners (title,subtitle,description,button1_text,button1_link,button2_text,button2_link,image_url,sort_order,is_active) VALUES (?,?,?,?,?,?,?,?,?,?)', [item.title,item.subtitle,item.description,item.button1_text,item.button1_link,item.button2_text,item.button2_link,item.image_url,item.sort_order,item.is_active]); return true; } if (section === 'subHeroBanners') { if (id) await db('UPDATE sub_hero_banners SET title=?,short_text=?,image_url=?,button_text=?,button_link=?,sort_order=?,is_active=? WHERE id=?', [item.title,item.short_text,item.image_url,item.button_text,item.button_link,item.sort_order,item.is_active,id]); else await db('INSERT INTO sub_hero_banners (title,short_text,image_url,button_text,button_link,sort_order,is_active) VALUES (?,?,?,?,?,?,?)', [item.title,item.short_text,item.image_url,item.button_text,item.button_link,item.sort_order,item.is_active]); return true; } if (section === 'mediaGallery') { if (id) await db('UPDATE media_gallery SET media_type=?,title=?,caption=?,file_url=?,category=?,is_featured=?,sort_order=?,is_active=? WHERE id=?', [item.media_type,item.title,item.caption,item.file_url,item.category,item.is_featured,item.sort_order,item.is_active,id]); else await db('INSERT INTO media_gallery (media_type,title,caption,file_url,category,is_featured,sort_order,is_active) VALUES (?,?,?,?,?,?,?,?)', [item.media_type,item.title,item.caption,item.file_url,item.category,item.is_featured,item.sort_order,item.is_active]); return true; } if (section === 'tiles') { if (id) await db('UPDATE homepage_tiles SET title=?,description=?,image_url=?,icon_name=?,bg_color=?,button_text=?,button_link=?,tile_size=?,sort_order=?,is_active=? WHERE id=?', [item.title,item.description,item.image_url,item.icon_name,lightBg(),item.button_text,item.button_link,item.tile_size,item.sort_order,item.is_active,id]); else await db('INSERT INTO homepage_tiles (title,description,image_url,icon_name,bg_color,button_text,button_link,tile_size,sort_order,is_active) VALUES (?,?,?,?,?,?,?,?,?,?)', [item.title,item.description,item.image_url,item.icon_name,lightBg(),item.button_text,item.button_link,item.tile_size,item.sort_order,item.is_active]); return true; } } catch {} return false; }

