app.get('/api/admin/posts', requireRole(['admin','editor','author']), async (req, res) => res.json({ success: true, posts: await loadPosts() }));
app.post('/api/posts', requireRole(['admin','editor','author']), async (req, res) => { const p = { id: Date.now(), title: req.body.title || 'Untitled Post', category: req.body.category || 'Viral India', excerpt: req.body.excerpt || '', content: req.body.content || '', language: req.body.language || 'en', cover_image: req.body.cover_image || '', hashtags: req.body.hashtags || '', created_at: new Date().toISOString() }; if (await insertPost(p)) res.json({ success: true, source: 'database', post: p }); else { memoryPosts.unshift(p); res.json({ success: true, source: 'memory', post: p }); } });
app.put('/api/posts/:id', requireRole(['admin','editor','author']), async (req, res) => { const id = Number(req.params.id); try { await db('UPDATE posts SET title=?,excerpt=?,content=?,category=?,language=?,cover_image=? WHERE id=?', [req.body.title, req.body.excerpt, req.body.content + '\n\n' + (req.body.hashtags || ''), req.body.category, req.body.language || 'en', req.body.cover_image || '', id]); res.json({ success: true, source: 'database' }); } catch { memoryPosts = memoryPosts.map(p => Number(p.id) === id ? { ...p, ...req.body } : p); res.json({ success: true, source: 'memory' }); } });
app.delete('/api/posts/:id', requireRole(['admin','editor']), async (req, res) => { const id = Number(req.params.id); try { await db('DELETE FROM posts WHERE id=?', [id]); res.json({ success: true, source: 'database' }); } catch { memoryPosts = memoryPosts.filter(p => Number(p.id) !== id); res.json({ success: true, source: 'memory' }); } });
app.post('/api/admin/seed-category-blogs', requireRole(['admin','editor']), async (req, res) => { let created = 0; for (const x of seedTexts) { const p = { title: x[1], category: x[0], excerpt: x[2], content: x[3], hashtags: '#India #VividIndia #' + x[0].replace(/\s/g, '') }; if (await insertPost(p)) created++; else { memoryPosts.unshift({ id: Date.now() + created, ...p, created_at: new Date().toISOString() }); created++; } } res.json({ success: true, created }); });
app.post('/api/admin/media/upload', requireRole(['admin','editor','author','media_manager']), async (req, res) => { try { const url = await saveUpload(req.body.dataUrl, req.body.title || 'media'); const asset = { id: Date.now(), title: req.body.title || 'Media', file_url: url, file_type: req.body.file_type || 'image', category: req.body.category || '', alt_text: req.body.alt_text || '', caption: req.body.caption || '', created_at: new Date().toISOString() }; try { await db('INSERT INTO media_assets (title,file_url,file_type,category,alt_text,caption,uploaded_by) VALUES (?,?,?,?,?,?,?)', [asset.title, asset.file_url, asset.file_type, asset.category, asset.alt_text, asset.caption, req.user.email]); } catch { memoryMedia.unshift(asset); } res.json({ success: true, url, asset }); } catch (e) { res.status(400).json({ success: false, message: e.message }); } });
