app.post('/api/admin/homepage/:section', requireRole(['admin','editor']), async (req, res) => { const s = req.params.section; const item = { id: Date.now(), ...req.body, bg_color: lightBg(), is_active: Number(req.body.is_active ?? 1), sort_order: Number(req.body.sort_order || 0) }; const ok = await saveHomeDb(s, item); if (!ok && memoryHome[s]) memoryHome[s].push(item); res.json({ success: true, source: ok ? 'database' : 'memory', item }); });
app.put('/api/admin/homepage/:section/:id', requireRole(['admin','editor']), async (req, res) => { const s = req.params.section, id = Number(req.params.id); const item = { ...req.body, bg_color: lightBg(), is_active: Number(req.body.is_active ?? 1), sort_order: Number(req.body.sort_order || 0) }; const ok = await saveHomeDb(s, item, id); if (!ok && memoryHome[s]) memoryHome[s] = memoryHome[s].map(x => Number(x.id) === id ? { ...x, ...item, id } : x); res.json({ success: true, source: ok ? 'database' : 'memory' }); });
app.delete('/api/admin/homepage/:section/:id', requireRole(['admin','editor']), async (req, res) => { const s = req.params.section, id = Number(req.params.id); try { await db('DELETE FROM ' + tableFor(s) + ' WHERE id=?', [id]); res.json({ success: true, source: 'database' }); } catch { if (memoryHome[s]) memoryHome[s] = memoryHome[s].filter(x => Number(x.id) !== id); res.json({ success: true, source: 'memory' }); } });
app.get('/api/ai/status', requireRole(['admin','editor','author']), (req, res) => res.json({ success: true, openaiConfigured: !!process.env.OPENAI_API_KEY, model: process.env.OPENAI_MODEL || 'gpt-4o-mini', imageModel: process.env.OPENAI_IMAGE_MODEL || 'gpt-image-1' }));
app.post('/api/ai/post-assist', requireRole(['admin','editor','author']), async (req, res) => { const fallback = humanFallback(req.body.category, req.body.title, req.body.content || req.body.idea, req.body.language); if (!process.env.OPENAI_API_KEY) return res.json({ success: true, source: 'human-fallback', suggestion: fallback }); try { const prompt = `Write like an experienced human magazine editor. Use only the supplied title and notes. Do not add unrelated facts, generic filler, or fake current-news details. Make it clear, grounded, natural, and useful for global readers. Return JSON only with title, category, excerpt, content, hashtags array. Category: ${req.body.category}. Title: ${req.body.title || ''}. Notes: ${req.body.content || req.body.idea || ''}. Language: ${req.body.language || 'en'}.`; const r = await fetch('https://api.openai.com/v1/chat/completions', { method: 'POST', headers: { Authorization: `Bearer ${process.env.OPENAI_API_KEY}`, 'Content-Type': 'application/json' }, body: JSON.stringify({ model: process.env.OPENAI_MODEL || 'gpt-4o-mini', messages: [{ role: 'system', content: 'You are a senior human editor for an India magazine. No generic AI tone. No unrelated information. No invented news facts. Return valid JSON only.' }, { role: 'user', content: prompt }], temperature: 0.45 }) }); const data = await r.json(); const text = data?.choices?.[0]?.message?.content || '{}'; res.json({ success: true, source: 'openai-human-editor', suggestion: { ...fallback, ...JSON.parse(text.replace(/```json|```/g, '').trim()) } }); } catch (e) { res.json({ success: true, source: 'human-fallback-error', message: e.message, suggestion: fallback }); } });
app.post('/api/ai/seo', requireRole(['admin','editor','author']), (req, res) => { const title = req.body.title || 'Vivid India Story'; const cat = req.body.category || 'India'; res.json({ success: true, seo: { meta_title: `${title} | YE MERA INDIA`, meta_description: `${title} explained in a clear, human magazine style for readers interested in ${cat} and India.`, keywords: [cat, 'India', 'Vivid India', 'Human stories', 'Indian culture'] } }); });
app.post('/api/ai/media-suggest', requireRole(['admin','editor','author','media_manager']), (req, res) => res.json({ success: true, suggestion: { prompt: `Bright editorial cover for ${req.body.title || req.body.category || 'India story'}, white background, saffron and green accents, Indian magazine style, human and premium, no clutter.`, caption: `A clean editorial visual for ${req.body.title || 'this story'}.` } }));
app.post('/api/ai/image-generate', requireRole(['admin','editor','media_manager','author']), async (req, res) => { const prompt = req.body.prompt || `Bright India magazine cover for ${req.body.title || 'YE MERA INDIA'}`; try { if (process.env.OPENAI_API_KEY) { const r = await fetch('https://api.openai.com/v1/images/generations', { method: 'POST', headers: { Authorization: `Bearer ${process.env.OPENAI_API_KEY}`, 'Content-Type': 'application/json' }, body: JSON.stringify({ model: process.env.OPENAI_IMAGE_MODEL || 'gpt-image-1', prompt, size: '1024x1024', n: 1 }) }); const d = await r.json(); const b64 = d?.data?.[0]?.b64_json; const urlFromApi = d?.data?.[0]?.url; if (b64) { const url = await saveUpload('data:image/png;base64,' + b64, req.body.title || 'ai-image'); return res.json({ success: true, source: 'openai-image', url, prompt }); } if (urlFromApi) return res.json({ success: true, source: 'openai-image-url', url: urlFromApi, prompt }); }
    const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="800"><defs><linearGradient id="g" x1="0" x2="1"><stop stop-color="#fff7ed"/><stop offset=".5" stop-color="#dcfce7"/><stop offset="1" stop-color="#dbeafe"/></linearGradient></defs><rect width="1200" height="800" fill="url(#g)"/><circle cx="980" cy="140" r="120" fill="#f97316" opacity=".18"/><circle cx="200" cy="620" r="160" fill="#22c55e" opacity=".15"/><text x="80" y="170" font-size="54" font-family="Georgia" fill="#ea580c" font-weight="700">YE MERA INDIA</text><text x="80" y="260" font-size="76" font-family="Georgia" fill="#111827" font-weight="700">${esc((req.body.title || 'Bright India Story').slice(0, 42))}</text><text x="80" y="350" font-size="34" font-family="Arial" fill="#475569">AI-assisted editorial cover placeholder</text><text x="80" y="650" font-size="48" font-family="Arial" fill="#111827">🙏 नमस्ते</text></svg>`; const dataUrl = 'data:image/svg+xml;base64,' + Buffer.from(svg).toString('base64'); const url = await saveUpload(dataUrl, req.body.title || 'ai-placeholder'); res.json({ success: true, source: 'fallback-svg', url, prompt }); } catch (e) { res.status(500).json({ success: false, message: e.message }); } });
